function diagramBlockRoot(e){return e.closest("div.highlight")||e.parentNode}document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("pre code.language-dot, pre code.dot").forEach(e=>{const t=e.textContent.replace(/&gt;/g,">").replace(/&lt;/g,"<"),n=new Viz;n.renderSVGElement(t).then(t=>{t.removeAttribute("width"),t.removeAttribute("height"),t.setAttribute("preserveAspectRatio","xMidYMid meet");const n=document.createElement("div");n.className="graphviz-diagram",n.appendChild(t);const s=diagramBlockRoot(e);s.parentNode.replaceChild(n,s)}).catch(t=>{console.error("Viz.js render error:",t),e.parentNode.textContent="Error rendering diagram: "+t})})})